UPDATE t_order
SET status = 'CANCELLED', cancel_type = #{cancelType}, cancel_time = #{cancelTime}
WHERE order_no = #{orderNo} AND status = 'PENDING_PAYMENT'

UPDATE t_order
SET status = 'PAID', paid_time = #{paidTime}
WHERE order_no = #{orderNo} AND status = #{fromStatus}

UPDATE t_order
SET status = 'REFUNDING'
WHERE order_no = #{orderNo}
  AND status IN

    #{s}

UPDATE t_order
SET status = #{targetStatus}
WHERE order_no = #{orderNo} AND status = 'REFUNDING'

UPDATE t_order
SET status = 'CANCELLED', cancel_type = 'TIMEOUT', cancel_time = #{cancelTime}
WHERE order_no IN

    #{no}

  AND status IN

    #{s}

  AND expired_time < #{cancelTime}
